import{a as e,b as o,_ as s}from"./chunks/image_3.BMltJ5JR.js";import{_ as r,o as a,c as i,ah as n}from"./chunks/framework.vkRkgbMn.js";const c="/projects/LeRobot/en/latest/assets/image_4.BApGrYA5.png",g="/projects/LeRobot/en/latest/assets/image_5._u3z1X-I.png",l="/projects/LeRobot/en/latest/assets/image_6.DEZEw-vR.png",p="/projects/LeRobot/en/latest/assets/image_7.CuoClLHv.png",h="/projects/LeRobot/en/latest/assets/image_8.DvPw90xD.png",m="/projects/LeRobot/en/latest/assets/image_9.qWJ5pNOY.png",d="/projects/LeRobot/en/latest/assets/image_12.DBjxyB2N.png",_="/projects/LeRobot/en/latest/assets/image_11.C1XyzuJV.png",w="/projects/LeRobot/en/latest/assets/image_10.DXSNaKCY.png",S=JSON.parse('{"title":"Magnetic Encoder Servo Firmware Flashing Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Magnetic Encoder Servo Firmware Flashing Tutorial.md","filePath":"docs/2_Magnetic Encoder Servo Firmware Flashing Tutorial.md"}'),u={name:"docs/2_Magnetic Encoder Servo Firmware Flashing Tutorial.md"};function f(b,t,v,y,k,C){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="magnetic-encoder-servo-firmware-flashing-tutorial" tabindex="-1">Magnetic Encoder Servo Firmware Flashing Tutorial <a class="header-anchor" href="#magnetic-encoder-servo-firmware-flashing-tutorial" aria-label="Permalink to &quot;Magnetic Encoder Servo Firmware Flashing Tutorial&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Taking HX-30HM as an example here,</strong></p></div><p><strong>Magnetic Encoder Servo</strong> PC Software Installation Package path: <a href="https://drive.google.com/drive/folders/1G2VSZiqwqcjcrp59oCFjL_C3VDzehWqo" target="_blank" rel="noreferrer">Appendix/ServoStudio_0.1.1_x64-setup.exe</a></p><p>The wiring diagram for the servo control board is shown below. Power the board with a 12V power supply and connect the servo control board to the computer using a Type-C cable. Connect the magnetic encoder servo to the board.</p><img loading="lazy" height="1163" width="1025" src="'+e+'" class="common_img" style="width:600px;"><p>Press <strong>Win+R</strong> to open the Control Panel, type <strong>devmgmt.msc</strong>, and open <strong>Device Manager</strong>.</p><img loading="lazy" height="1088" width="897" src="'+o+'" class="common_img" style="width:500px;"><p>Click <strong>Ports</strong> to view the port number; here, the port number is <strong>COM10</strong>.</p><img loading="lazy" height="540" width="543" src="'+c+'" class="common_img" style="width:800px;"><p>Double-click to open the software <img loading="lazy" height="1088" width="1446" src="'+s+'" style="width:55px;">.</p><p>Follow the steps:<br> Change the <strong>Port</strong> number to the one found (in this case, change to <strong>COM10</strong>)<br> -&gt; Set the baud rate for <strong>HX-30HM</strong> to 1000000</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The baud rate may vary for different magnetic encoder servos. Refer to the corresponding model&#39;s user manual for specifics.</strong></p></div><p>-&gt; Click <strong>Connect</strong> -&gt; Click <strong>Scan</strong></p><img loading="lazy" height="902" width="1402" src="'+g+'" class="common_img" style="width:1200px;"><p>The system will scan all servo <code>ID</code>. If a servo is detected, a servo control interface will appear, as shown in the image below.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If no servo is detected, unplug and re-plug the servo for testing.</strong></p></div><img loading="lazy" height="902" width="1402" src="'+l+'" class="common_img" style="width:1200px;"><p>Click <strong>Firmware</strong> -&gt; Click <strong>Click or drag firmware file here.</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+p+'" class="common_img" style="width:1200px;"><p>Click the <strong>HX-30HM_V3.9_20251023.sfw</strong> firmware package -&gt; Click <strong>Open</strong>.</p><img loading="lazy" height="533" width="946" src="'+h+'" class="common_img" style="width:800px;"><p>Click <strong>Force Upgrade</strong> -&gt; Click <strong>Upgrade</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+m+'" class="common_img" style="width:1200px;"><p>When the following screen appears, it indicates that the flashing process has started. At this point, unplug and re-plug the servo wire.</p><img loading="lazy" height="1009" width="1920" src="'+d+'" class="common_img" style="width:1200px;"><p>When the red box appears, it indicates the servo firmware has been successfully flashed.</p><img loading="lazy" height="1009" width="1920" src="'+_+'" class="common_img" style="width:1200px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If a &quot;Handshake Failed&quot; message appears (as shown in the image below), follow the steps in the documentation to proceed again. Click &quot;Upgrade&quot; and retry the firmware flashing process.</strong></p></div><img loading="lazy" height="1009" width="1920" src="'+w+'" class="common_img" style="width:1200px;">',29)])])}const F=r(u,[["render",f]]);export{S as __pageData,F as default};
